mapper.select:
SELECT t.id, t.name, t.create_by, t.create_time, COALESCE(article_count.article_count, 0) AS articleCount, COALESCE(essay_count.essay_count, 0) AS essayCount FROM tag t LEFT JOIN ( SELECT tag_id, COUNT(*) AS article_count FROM article_tag GROUP BY tag_id ) article_count ON t.id = article_count.tag_id LEFT JOIN ( SELECT tag_id, COUNT(*) AS essay_count FROM essay_tag GROUP BY tag_id ) essay_count ON t.id = essay_count.tag_id
AND t.name LIKE CONCAT('%', #{name}, '%')
ORDER BY t.id DESC LIMIT #{offset}, #{size}
